#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"; IMAGE='mysql@sha256:c831a0f11348d402b43d77453e17d770be2eef356615a2823fe0f5a0d6c8b9af'; SOCKET=/var/run/docker.sock; RH="$(openssl rand -hex 16)"; RID="${RH:0:8}-${RH:8:4}-4${RH:13:3}-a${RH:17:3}-${RH:20:12}"; HEX="${RID//-/}"; NAME="jc-fl-concurrency-$HEX"; DB="jc_fl_e2e_$HEX"; SD="$(mktemp -d)"; C=''
d(){ docker -H unix://$SOCKET "$@"; }; cleanup(){ [ -z "$C" ]||d rm -f "$C" >/dev/null 2>&1||true; rm -rf "$SD"; }; trap cleanup EXIT
fail(){ echo "fair_launch_mysql8_reversal_concurrency_test: FAIL: $*" >&2; exit 1; }
openssl rand -hex 32 >"$SD/root"; C="$(d run -d --name "$NAME" --label joincare.fair-launch.local-e2e-run="$RID" --network none --tmpfs /var/lib/mysql:rw,size=2g --tmpfs /tmp:rw,size=256m -v "$SD/root:/run/secrets/root:ro" -v "$ROOT:/repo:ro" -e MYSQL_ROOT_PASSWORD_FILE=/run/secrets/root "$IMAGE" --skip-log-bin)"
d exec "$C" sh -c 'umask 077;{ echo [client];echo user=root;printf password=;cat /run/secrets/root;echo host=127.0.0.1;echo protocol=tcp;} >/tmp/root.cnf'
for _ in $(seq 1 90);do d exec "$C" mysqladmin --defaults-extra-file=/tmp/root.cnf ping --silent >/dev/null 2>&1&&break;sleep 1;done
m(){ d exec -i "$C" mysql --defaults-extra-file=/tmp/root.cnf --batch --raw --skip-column-names "$@"; }
printf 'CREATE DATABASE `%s`;\n' "$DB"|m; printf 'CREATE TABLE schema_migrations(filename VARCHAR(255) PRIMARY KEY,checksum CHAR(64),status VARCHAR(16),applied_at DATETIME(6));\n'|m "$DB"
while read -r s f;do printf "INSERT INTO schema_migrations VALUES('%s','%s','applied',NOW(6));\n" "${f#\*}" "$s"|m "$DB";done<"$ROOT/migrations/baseline/fair-launch-pre-2026-09-03-ledger.sha256"
m "$DB"<"$ROOT/migrations/baseline/fair-launch-pre-2026-09-03.sql"
for f in 03_fair_launch_project_model 04_fair_launch_ce_v2_governance 05_fair_launch_signing_release_control 06_fair_launch_action_execution 07_fair_launch_position_projection;do { echo 'SET @JC_FAIR_LAUNCH_MIGRATION_APPROVED=1;';cat "$ROOT/migrations/2026_09_$f.sql";}|m "$DB";done
for f in 08_fair_launch_local_e2e_binding 09_fair_launch_financial_projection_v3 10_fair_launch_governance_projection_v3 11_fair_launch_effect_lineage_v3 12_fair_launch_typed_ledger_v3;do { echo 'SET @JC_FAIR_LAUNCH_LOCAL_E2E_APPROVED=1;';echo "SET @JC_FAIR_LAUNCH_LOCAL_E2E_RUN_ID='$RID';";cat "$ROOT/migrations/2026_09_$f.sql";}|m "$DB";done
cat <<SQL|m "$DB"
SET FOREIGN_KEY_CHECKS=1;
INSERT INTO projects(id,project_id,contract_version,funding_mode,description,tags,team_info,roadmap,partners,token_price_raw,hard_cap_raw,soft_cap_raw,max_per_user_raw,total_raised_raw,sale_token_amount_raw,min_contribution_raw,max_contribution_raw) VALUES(700001,700001,'fair_launch_v1','fair_launch','','[]','','','','0','0','1','0','0','1000','1',NULL);
INSERT INTO chain_contract_source(id,chain_id,contract_address,contract_version,funding_mode,registered_at,start_block,enabled) VALUES(700002,31337,'0x1111111111111111111111111111111111111111','fair_launch_v1','fair_launch',NOW(6),1,1);
INSERT INTO chain_contract_source_revision(id,source_id,revision_no,activation_block_hash,proxy_kind,abi_digest,confirmation_policy,governance_tx_hash,governance_operation_id,implementation_address,implementation_code_hash,dependency_manifest_digest,abi_version,from_block_number,from_transaction_index,from_tx_log_ordinal_inclusive,created_at) VALUES(700003,700002,1,CONCAT('0x',REPEAT('1',64)),'uups',REPEAT('2',64),'20_blocks',CONCAT('0x',REPEAT('3',64)),CONCAT('0x',REPEAT('4',64)),'0x5555555555555555555555555555555555555555',REPEAT('5',64),REPEAT('6',64),'fair-launch-v1',1,0,0,NOW(6));
INSERT INTO fair_launch_local_e2e_run(run_id,environment,exact_rpc_url,redis_endpoint,chain_id,database_name,mysql_server_uuid,mysql_version,container_id,owner_label_digest,schema_generation,baseline_digest,migration_manifest_digest,schema_digest,grant_digest,source_registry_digest,hardhat_genesis_hash,chain_manifest_digest,deployment_manifest_digest,runtime_admission_digest,created_at,expires_at,state) VALUES('$RID','local-e2e','http://127.0.0.1:18545','127.0.0.1:16379',31337,'$DB','00000000-0000-0000-0000-000000000001','8.4.10','$C',REPEAT('a',64),12,REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),REPEAT('e',64),REPEAT('f',64),CONCAT('0x',REPEAT('1',64)),REPEAT('2',64),REPEAT('3',64),REPEAT('4',64),NOW(6),DATE_ADD(NOW(6),INTERVAL 1 HOUR),'verified');
INSERT INTO fair_launch_source_revision_binding_v3(id,run_row_id,chain_id,source_id,source_revision_id,from_block_number,from_transaction_index,from_tx_log_ordinal_inclusive,source_binding_digest,created_at) SELECT 700004,id,31337,700002,700003,1,0,0,REPEAT('a',64),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='$RID';
INSERT INTO fair_launch_project_binding_v3(id,run_row_id,project_row_id,chain_id,contract_address,contract_version,project_id,project_id_raw,source_binding_id,source_id,source_revision_id,project_token_address,project_token_decimals,payment_token_address,payment_token_decimals,binding_digest,created_at) SELECT 700005,id,700001,31337,'0x1111111111111111111111111111111111111111','fair_launch_v1',700001,'700001',700004,700002,700003,'0x4444444444444444444444444444444444444444',18,'0x6666666666666666666666666666666666666666',6,REPEAT('b',64),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='$RID';
INSERT INTO fair_launch_source_token_binding_v3(id,run_row_id,chain_id,source_id,contract_address,token_address,token_decimals,metadata_version,admission_generation,runtime_code_hash,metadata_digest,admitted_at) SELECT 700006,id,31337,700002,'0x1111111111111111111111111111111111111111','0x4444444444444444444444444444444444444444',18,1,1,REPEAT('7',64),REPEAT('8',64),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='$RID';
SQL
fk(){ [ "$(printf 'SELECT @@FOREIGN_KEY_CHECKS;\n'|m "$DB")" = 1 ]||fail 'FOREIGN_KEY_CHECKS is not 1'; }
setup_pair(){ local b="$1" e=$((b+10000)) p=$((b+20000)) a=$((b+30000)); fk; cat <<SQL|m "$DB"
INSERT INTO chain_event_identity_v2(id,chain_id,tx_hash,tx_log_ordinal,created_at) VALUES($e,31337,CONCAT('0x',LPAD(LOWER(HEX($e)),64,'0')),0,NOW(6));
INSERT INTO chain_event_placement_v2(id,event_identity_id,generation,block_number,block_hash,transaction_index,rpc_log_index,source_revision_id,canonical_slot,finalized_at) VALUES($p,$e,1,$p,CONCAT('0x',LPAD(LOWER(HEX($p)),64,'0')),0,0,700003,NULL,NOW(6)),($((p+1)),$e,2,$((p+1)),CONCAT('0x',LPAD(LOWER(HEX($((p+1)))),64,'0')),0,0,700003,NULL,NOW(6));
INSERT INTO chain_event_application_attempt_v2(id,event_identity_id,placement_id,effect_version,expected_effect,attempt_no,disposition,effect_digest,applied_at) VALUES($a,$e,$p,1,1,1,'exact',REPEAT('a',64),NOW(6)),($((a+1)),$e,$((p+1)),1,1,2,'exact',REPEAT('b',64),NOW(6));
INSERT INTO fair_launch_application_lineage_v3(id,ce_application_attempt_id,run_row_id,chain_id,source_binding_id,source_id,event_identity_id,placement_id,source_revision_id,effect_manifest_version,placement_generation,predecessor_lineage_id,reverses_lineage_id,disposition,expected_effect,payload_digest,effect_digest,ledger_digest,mutation_digest,state,applied_at,created_at) SELECT $b,$a,id,31337,700004,700002,$e,$p,700003,1,1,NULL,NULL,'forward',1,REPEAT('a',64),REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),'applied',NOW(6),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='$RID';
INSERT INTO fair_launch_application_lineage_v3(id,ce_application_attempt_id,run_row_id,chain_id,source_binding_id,source_id,event_identity_id,placement_id,source_revision_id,effect_manifest_version,placement_generation,predecessor_lineage_id,reverses_lineage_id,disposition,expected_effect,payload_digest,effect_digest,ledger_digest,mutation_digest,state,applied_at,created_at) SELECT $((b+1)),$((a+1)),id,31337,700004,700002,$e,$((p+1)),700003,1,2,NULL,$b,'reversal',1,REPEAT('a',64),REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),'applied',NOW(6),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='$RID';
INSERT INTO chain_event_identity_v2(id,chain_id,tx_hash,tx_log_ordinal,created_at) VALUES($((e+1)),31337,CONCAT('0x',LPAD(LOWER(HEX($((e+1)))),64,'0')),0,NOW(6));
INSERT INTO chain_event_placement_v2(id,event_identity_id,generation,block_number,block_hash,transaction_index,rpc_log_index,source_revision_id,canonical_slot,finalized_at) VALUES($((p+2)),$((e+1)),1,$((p+2)),CONCAT('0x',LPAD(LOWER(HEX($((p+2)))),64,'0')),0,0,700003,NULL,NOW(6));
INSERT INTO chain_event_application_attempt_v2(id,event_identity_id,placement_id,effect_version,expected_effect,attempt_no,disposition,effect_digest,applied_at) VALUES($((a+2)),$((e+1)),$((p+2)),1,1,1,'exact',REPEAT('c',64),NOW(6));
INSERT INTO fair_launch_application_lineage_v3(id,ce_application_attempt_id,run_row_id,chain_id,source_binding_id,source_id,event_identity_id,placement_id,source_revision_id,effect_manifest_version,placement_generation,predecessor_lineage_id,reverses_lineage_id,disposition,expected_effect,payload_digest,effect_digest,ledger_digest,mutation_digest,state,applied_at,created_at) SELECT $((b+2)),$((a+2)),id,31337,700004,700002,$((e+1)),$((p+2)),700003,1,1,NULL,NULL,'forward',1,REPEAT('a',64),REPEAT('b',64),REPEAT('c',64),REPEAT('d',64),'applied',NOW(6),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='$RID';
SQL
fk; }
prepare_case(){ local name="$1" b="$2" e=$((b+10000)) p=$((b+20000)); case "$name" in
 journal_reversal_link) printf "INSERT INTO fair_launch_effect_journal_v3 VALUES(%s,(SELECT id FROM fair_launch_local_e2e_run WHERE run_id='%s'),31337,700002,%s,%s,700003,%s,1,'mutate','project','x',1,'{}',REPEAT('a',64),'{}',REPEAT('b',64),NOW(6));
" "$((b+50000))" "$RID" "$e" "$p" "$b"|m "$DB";;
 reversal_evidence_item) printf "INSERT INTO fair_launch_effect_journal_v3 VALUES(%s,(SELECT id FROM fair_launch_local_e2e_run WHERE run_id='%s'),31337,700002,%s,%s,700003,%s,1,'mutate','project','x',1,'{}',REPEAT('a',64),'{}',REPEAT('b',64),NOW(6));\n" "$((b+50000))" "$RID" "$e" "$p" "$b"|m "$DB";;
 project_compensation_ledger) printf "INSERT INTO fair_launch_ledger_entry_v3 VALUES(%s,(SELECT id FROM fair_launch_local_e2e_run WHERE run_id='%s'),31337,700002,700005,700001,'0x1111111111111111111111111111111111111111','fair_launch_v1','0x2222222222222222222222222222222222222222','0x3333333333333333333333333333333333333333','payment_contributed','payment','inflow','0x6666666666666666666666666666666666666666',6,'1','0.000001',%s,%s,%s,700003,1,1,NULL,NULL,REPEAT('a',64),NOW(6));
" "$((b+50000))" "$RID" "$e" "$p" "$b"|m "$DB";;
 policy_history) printf "INSERT INTO fair_launch_policy_current_v3(id,run_row_id,chain_id,source_id,latest_source_revision_id,policy_kind,subject_address,policy_version,enabled,emergency_blocked,token_decimals,runtime_code_hash,policy_digest,attestation_digest,state_generation,last_event_identity_id,last_placement_id,last_source_revision_id,last_effect_manifest_version,last_application_attempt_id,source_application_lineage_id,state_digest,updated_at) SELECT %s,id,31337,700002,700003,'project_token_policy','0x4444444444444444444444444444444444444444',1,1,0,18,REPEAT('7',64),REPEAT('8',64),REPEAT('9',64),1,%s,%s,700003,1,%s,%s,REPEAT('a',64),NOW(6) FROM fair_launch_local_e2e_run WHERE run_id='%s';\n" "$((b+60000))" "$e" "$p" "$((b+30000))" "$b" "$RID"|m "$DB";;
 governance_compensation_ledger) printf "INSERT INTO fair_launch_governance_ledger_entry_v3 VALUES(%s,(SELECT id FROM fair_launch_local_e2e_run WHERE run_id='%s'),31337,700002,'0x1111111111111111111111111111111111111111',700006,'excess_tokens_recovered','governance_token','outflow','0x4444444444444444444444444444444444444444','0x2222222222222222222222222222222222222222',18,'1','0.000000000000000001',%s,%s,%s,700003,1,1,NULL,NULL,REPEAT('a',64),NOW(6));
" "$((b+50000))" "$RID" "$b" "$e" "$p"|m "$DB";; esac; fk; }
closure_sql(){ local name="$1" b="$2"; local sj=0 sl=0 sg=0 item='' actual=''; case "$name" in journal_reversal_link|reversal_evidence_item) sj=1;actual="INSERT INTO fair_launch_journal_reversal_v3 VALUES($((b+50000)),$b,$((b+1)),@created);";item="SET @kind='source_journal';SET @eid=$((b+50000));SET @ed=REPEAT('b',64);";; project_compensation_ledger) sl=1;actual="INSERT INTO fair_launch_ledger_entry_v3 VALUES($((b+50001)),(SELECT id FROM fair_launch_local_e2e_run WHERE run_id='$RID'),31337,700002,700005,700001,'0x1111111111111111111111111111111111111111','fair_launch_v1','0x2222222222222222222222222222222222222222','0x3333333333333333333333333333333333333333','payment_contributed_reversal','payment','compensation','0x6666666666666666666666666666666666666666',6,'1','0.000001',$((b+10000)),$((b+20001)),$((b+1)),700003,1,1,$((b+50000)),2,REPEAT('b',64),@created);";item="SET @kind='source_ledger';SET @eid=$((b+50000));SET @ed=REPEAT('a',64);";; governance_compensation_ledger) sg=1;actual="INSERT INTO fair_launch_governance_ledger_entry_v3 VALUES($((b+50001)),(SELECT id FROM fair_launch_local_e2e_run WHERE run_id='$RID'),31337,700002,'0x1111111111111111111111111111111111111111',700006,'excess_tokens_recovered_reversal','governance_token','compensation','0x4444444444444444444444444444444444444444','0x2222222222222222222222222222222222222222',18,'1','0.000000000000000001',$((b+1)),$((b+10000)),$((b+20001)),700003,1,1,$((b+50000)),2,REPEAT('b',64),@created);";item="SET @kind='source_governance_ledger';SET @eid=$((b+50000));SET @ed=REPEAT('a',64);";; esac; local total=$((sj+sl+sg)); cat <<SQL
START TRANSACTION; SET @created='2026-09-10 00:00:00.000000'; INSERT INTO fair_launch_lineage_reversal_v3 VALUES($b,$((b+1)),@created,@created); $actual SET @seed=LOWER(SHA2(CONCAT('JC_FL_REVERSAL_EVIDENCE_V1',LPAD(HEX($b),16,'0'),LPAD(HEX($((b+1))),16,'0')),256)); $item
$(if [ "$total" = 1 ];then echo "SET @item=LOWER(SHA2(CONCAT('JC_FL_REVERSAL_EVIDENCE_ITEM_V1',@seed,LPAD(HEX(1),16,'0'),LPAD(HEX(OCTET_LENGTH(@kind)),8,'0'),HEX(@kind),LPAD(HEX(@eid),16,'0'),@ed),256)); INSERT INTO fair_launch_reversal_evidence_item_v3 VALUES($b,$((b+1)),1,@kind,@eid,@ed,@seed,@item,@created);";else echo 'SET @item=@seed;';fi)
SET @manifest=LOWER(SHA2(CONCAT('JC_FL_REVERSAL_MANIFEST_V1',LPAD(HEX($b),16,'0'),LPAD(HEX($((b+1))),16,'0'),LPAD(HEX($sj),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX($sl),16,'0'),LPAD(HEX($sg),16,'0'),LPAD(HEX($total),16,'0'),@item),256)); INSERT INTO fair_launch_reversal_evidence_manifest_v3 VALUES($b,$((b+1)),$sj,0,0,0,0,0,$sl,$sg,$total,@item,@manifest,@created);
SET @closure=LOWER(SHA2(CONCAT('JC_FL_REVERSAL_CLOSURE_V1',LPAD(HEX($b),16,'0'),LPAD(HEX($((b+1))),16,'0'),@manifest,LPAD(HEX($sj),16,'0'),LPAD(HEX($sj),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX(0),16,'0'),LPAD(HEX($sl),16,'0'),LPAD(HEX($sl),16,'0'),LPAD(HEX($sg),16,'0'),LPAD(HEX($sg),16,'0'),DATE_FORMAT(@created,'%Y-%m-%dT%H:%i:%s.%fZ')),256)); INSERT INTO fair_launch_reversal_closure_v3 VALUES($b,$((b+1)),@manifest,$sj,$sj,0,0,0,0,0,$sl,$sl,$sg,$sg,@closure,@created); DO SLEEP(5); COMMIT;
SQL
}
classes=0; waits=0; closures=0; fk_checks=0; exact_errors=0; residues=0
run_case(){ local name="$1" b="$2" sql="$3" table="$4" predicate="$5" baseline="$6"; setup_pair "$b";prepare_case "$name" "$b";fk; local pre="$SD/$name.preflight"; if [ "$name" = lineage_reversal_link ]; then printf "START TRANSACTION; %s; ROLLBACK;\n" "$sql"; else printf "START TRANSACTION; INSERT INTO fair_launch_lineage_reversal_v3 VALUES(%s,%s,NOW(6),NOW(6)); %s; ROLLBACK;\n" "$b" "$((b+1))" "$sql"; fi |m "$DB">"$pre" 2>&1 || { cat "$pre" >&2; fail "$name candidate invalid before closure"; }; local co="$SD/$name.close" lo="$SD/$name.late"; closure_sql "$name" "$b"|m "$DB">"$co" 2>&1& cp=$!; holder='';for _ in $(seq 1 240);do holder="$(printf "SELECT COALESCE(MAX(ID),'') FROM information_schema.PROCESSLIST WHERE DB='$DB' AND INFO LIKE 'DO SLEEP(5)%%';\n"|m information_schema|tail -1)";[ -n "$holder" ]&&break;sleep .025;done;[ -n "$holder" ]||{ cat "$co" >&2;fail "$name holder missing";};fk
 printf "SELECT @@FOREIGN_KEY_CHECKS; SET innodb_lock_wait_timeout=10; %s; SELECT 'LATE_COMMITTED'; SELECT @@FOREIGN_KEY_CHECKS;\n" "$sql"|m "$DB">"$lo" 2>&1& lp=$!; waiter='';for _ in $(seq 1 240);do waiter="$(printf "SELECT COALESCE(MAX(rt.PROCESSLIST_ID),'') FROM performance_schema.data_lock_waits w JOIN performance_schema.data_locks req ON req.ENGINE_LOCK_ID=w.REQUESTING_ENGINE_LOCK_ID JOIN performance_schema.data_locks blk ON blk.ENGINE_LOCK_ID=w.BLOCKING_ENGINE_LOCK_ID JOIN performance_schema.threads rt ON rt.THREAD_ID=req.THREAD_ID JOIN performance_schema.threads bt ON bt.THREAD_ID=blk.THREAD_ID WHERE bt.PROCESSLIST_ID=$holder AND req.OBJECT_SCHEMA='$DB' AND req.OBJECT_NAME='fair_launch_reversal_serialization_guard_v3';\n"|m performance_schema|tail -1)";[ -n "$waiter" ]&&break;sleep .025;done;[ -n "$waiter" ]||{ cat "$lo" >&2;fail "$name exact guard waiter missing";}; waits=$((waits+1));wait "$cp"||{ cat "$co" >&2;fail "$name closure failed";};set +e;wait "$lp";rc=$?;set -e;[ "$rc" -ne 0 ]||fail "$name late insert committed";[ "$(grep -Fxc 'ERROR 1644 (45000) at line 1: Fair Launch reversal closure is final' "$lo")" -eq 1 ]||{ cat "$lo" >&2;fail "$name wrong loser";};[ "$(grep -c '^ERROR ' "$lo")" -eq 1 ]||fail "$name multiple loser errors";exact_errors=$((exact_errors+1));fk;fk_checks=$((fk_checks+1))
 [ "$(printf "SELECT state FROM fair_launch_reversal_serialization_guard_v3 WHERE reversed_lineage_id=$b;\n"|m "$DB")" = closed ]||fail "$name guard";[ "$(printf "SELECT COUNT(*) FROM fair_launch_reversal_closure_v3 WHERE reversed_lineage_id=$b;\n"|m "$DB")" = 1 ]||fail "$name closure";closures=$((closures+1));[ "$(printf "SELECT COUNT(*) FROM $table WHERE $predicate;\n"|m "$DB")" = "$baseline" ]||fail "$name residue";residues=$((residues+1));classes=$((classes+1));echo "concurrency:$name PASS holder=$holder waiter=$waiter exact_error='Fair Launch reversal closure is final'"
}
